CREATE DATABASE IF NOT EXISTS farm2market; USE farm2market;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(15),password_hash VARCHAR(100) NOT NULL,role ENUM('farmer','buyer') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE farmers(user_id INT PRIMARY KEY,farm_name VARCHAR(120),location VARCHAR(120),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE buyers(user_id INT PRIMARY KEY,buyer_type ENUM('household','restaurant','retailer','supermarket','hotel','hostel') DEFAULT 'household',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) UNIQUE NOT NULL);
INSERT INTO categories(name) VALUES('Vegetables'),('Fruits'),('Grains'),('Pulses'),('Dairy'),('Spices');
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,farmer_id INT NOT NULL,category_id INT NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,unit VARCHAR(10) DEFAULT 'kg',quantity DECIMAL(10,2) NOT NULL,image VARCHAR(200),location VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(farmer_id) REFERENCES farmers(user_id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE cart(id INT AUTO_INCREMENT PRIMARY KEY,buyer_id INT NOT NULL,product_id INT NOT NULL,quantity DECIMAL(10,2) NOT NULL,UNIQUE(buyer_id,product_id),FOREIGN KEY(buyer_id) REFERENCES buyers(user_id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE addresses(id INT AUTO_INCREMENT PRIMARY KEY,buyer_id INT NOT NULL,full_name VARCHAR(100),phone VARCHAR(15),email VARCHAR(150),address VARCHAR(255),city VARCHAR(80),state VARCHAR(80),pincode VARCHAR(6),FOREIGN KEY(buyer_id) REFERENCES buyers(user_id) ON DELETE CASCADE);
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,buyer_id INT NOT NULL,address_id INT NOT NULL,subtotal DECIMAL(10,2),delivery_charge DECIMAL(10,2),total DECIMAL(10,2),payment_status ENUM('Pending','Paid','Failed','Cancelled') DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(buyer_id) REFERENCES buyers(user_id),FOREIGN KEY(address_id) REFERENCES addresses(id));
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,farmer_id INT NOT NULL,quantity DECIMAL(10,2),price DECIMAL(10,2),status ENUM('Placed','Confirmed','Packed','Shipped','Delivered') DEFAULT 'Placed',FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,razorpay_order_id VARCHAR(60) UNIQUE,razorpay_payment_id VARCHAR(60),razorpay_signature VARCHAR(200),amount DECIMAL(10,2),status ENUM('created','success','failed','cancelled') DEFAULT 'created',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,buyer_id INT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,buyer_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(buyer_id) REFERENCES buyers(user_id));
